class Solution {
    public int minimumVisitedCells(int[][] grid){
        int rows=grid.length,cols=grid[0].length;
        TreeSet<Integer>[] rowUnvisited=new TreeSet[rows],colUnvisited=new TreeSet[cols];
        for(int row=0;row<rows;row++){
            rowUnvisited[row]=new TreeSet<>();
            for(int col=0;col<cols;col++)rowUnvisited[row].add(col);
        }
        for(int col=0;col<cols;col++){
            colUnvisited[col]=new TreeSet<>();
            for(int row=0;row<rows;row++)colUnvisited[col].add(row);
        }
        int[][] distance=new int[rows][cols];
        for(int[] line:distance)Arrays.fill(line,-1);
        distance[0][0]=1;
        rowUnvisited[0].remove(0);
        colUnvisited[0].remove(0);
        Queue<int[]> queue=new ArrayDeque<>();
        queue.add(new int[]{
            0,0
        });
        while(!queue.isEmpty()){
            int[] cell=queue.poll();
            int row=cell[0],col=cell[1],limit=grid[row][col];
            int maximumCol=Math.min(cols-1,col+limit);
            Integer nextCol=rowUnvisited[row].ceiling(col+1);
            while(nextCol!=null&&nextCol<=maximumCol){
                int destination=nextCol;
                rowUnvisited[row].remove(destination);
                colUnvisited[destination].remove(row);
                distance[row][destination]=distance[row][col]+1;
                queue.add(new int[]{
                    row,destination
                });
                nextCol=rowUnvisited[row].ceiling(col+1);
            }
            int maximumRow=Math.min(rows-1,row+limit);
            Integer nextRow=colUnvisited[col].ceiling(row+1);
            while(nextRow!=null&&nextRow<=maximumRow){
                int destination=nextRow;
                colUnvisited[col].remove(destination);
                rowUnvisited[destination].remove(col);
                distance[destination][col]=distance[row][col]+1;
                queue.add(new int[]{
                    destination,col
                });
                nextRow=colUnvisited[col].ceiling(row+1);
            }
        }
        return distance[rows-1][cols-1];
    }
}

