class Solution {
    fun minimumVisitedCells(grid:Array<IntArray>):Int{
        val rows=grid.size;
        val cols=grid[0].size;
        val rowUnvisited=Array(rows){
            java.util.TreeSet<Int>()
        };
        val colUnvisited=Array(cols){
            java.util.TreeSet<Int>()
        };
        for(row in 0 until rows)for(col in 0 until cols){
            rowUnvisited[row].add(col);
            colUnvisited[col].add(row)
        };
        val distance=Array(rows){
            IntArray(cols){
                -1
            }
        };
        distance[0][0]=1;
        rowUnvisited[0].remove(0);
        colUnvisited[0].remove(0);
        val queue=java.util.ArrayDeque<IntArray>();
        queue.add(intArrayOf(0,0));
        while(queue.isNotEmpty()){
            val cell=queue.removeFirst();
            val row=cell[0];
            val col=cell[1];
            val limit=grid[row][col];
            val maximumCol=minOf(cols-1,col+limit);
            var nextCol=rowUnvisited[row].ceiling(col+1);
            while(nextCol!=null&&nextCol<=maximumCol){
                val destination=nextCol;
                rowUnvisited[row].remove(destination);
                colUnvisited[destination].remove(row);
                distance[row][destination]=distance[row][col]+1;
                queue.add(intArrayOf(row,destination));
                nextCol=rowUnvisited[row].ceiling(col+1)
            };
            val maximumRow=minOf(rows-1,row+limit);
            var nextRow=colUnvisited[col].ceiling(row+1);
            while(nextRow!=null&&nextRow<=maximumRow){
                val destination=nextRow;
                colUnvisited[col].remove(destination);
                rowUnvisited[destination].remove(col);
                distance[destination][col]=distance[row][col]+1;
                queue.add(intArrayOf(destination,col));
                nextRow=colUnvisited[col].ceiling(row+1)
            }
        };
        return distance[rows-1][cols-1]
    }
}

